import{_ as o,o as e,c as d,a4 as r}from"./chunks/framework.BBs01uty.js";const p=JSON.parse('{"title":"09 · 设计决策与面试复盘","description":"","frontmatter":{},"headers":[],"relativePath":"template-editor/09-decisions.md","filePath":"template-editor/09-decisions.md"}'),a={name:"template-editor/09-decisions.md"};function n(s,t,i,h,l,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="_09-·-设计决策与面试复盘" tabindex="-1">09 · 设计决策与面试复盘 <a class="header-anchor" href="#_09-·-设计决策与面试复盘" aria-label="Permalink to &quot;09 · 设计决策与面试复盘&quot;">​</a></h1><blockquote><p>目标：把前八篇的&quot;怎么做&quot;收束成&quot;为什么这么选&quot;，并整理真实难点和高频追问，用于面试前回顾。</p><p><strong>阅读约定</strong>：本页每条都标注来源 —— <code>【文档】</code> 表示原设计记录里明确写了；<code>【推导】</code> 表示文档没直接写、但能从项目事实推出的答题框架，<strong>面试前请用你自己的真实经历核对一遍再讲</strong>。</p></blockquote><h2 id="一、关键设计决策" tabindex="-1">一、关键设计决策 <a class="header-anchor" href="#一、关键设计决策" aria-label="Permalink to &quot;一、关键设计决策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>决策</th><th>选择</th><th>理由</th><th>来源</th></tr></thead><tbody><tr><td>对外形态</td><td>Web Component</td><td>宿主技术栈不可控，需要框架无关的接入方式</td><td>【文档】</td></tr><tr><td>内容样式</td><td>内联样式</td><td>内容会导出到编辑器之外（邮件客户端 / PDF 渲染器），那里没有你的 CSS 文件</td><td>【文档】</td></tr><tr><td>交互样式</td><td>Tailwind + Shadow DOM</td><td>只活在编辑器内部，快速开发且需隔离</td><td>【文档】</td></tr><tr><td>数据源</td><td>DocNode 为 Single Source of Truth</td><td>DOM 不适合直接持久化 / diff / 跨端渲染</td><td>【文档】</td></tr><tr><td>操作封装</td><td>Command 模式</td><td>所有编辑操作统一收口，新增工具不动引擎</td><td>【文档】</td></tr><tr><td>Command 通信</td><td>经 CommandContext 代理</td><td>Command 不引用 Manager，可独立单测、拿不到不该拿的状态</td><td>【文档】</td></tr><tr><td>撤销机制</td><td>快照 + diff，而非逆操作</td><td>复合操作（拖入变量 = 插入 + 绑数据 + 应用样式）逆操作难写易错</td><td>【文档】</td></tr><tr><td>模型 ↔ DOM 定位</td><td><code>dataset.nodeId</code> 双向桥</td><td>保住 model 是纯数据层（无 DOM 依赖、可序列化）</td><td>【文档】</td></tr><tr><td>编辑期同步</td><td>事件驱动靶向更新，不做 diff</td><td>操作类型 + 目标 + 内容都已知，diff 是多余的</td><td>【文档】</td></tr><tr><td>Handler 契约</td><td><code>update</code> 可选</td><td>简单组件重建即可，复杂组件才值得原地 patch</td><td>【文档】</td></tr><tr><td>编辑器选型</td><td>自研而非 Quill/Slate/CKEditor</td><td>通用富文本编辑器不原生表达 FreeMarker 语义（变量 chip / 条件块 / 循环块是自定义节点），且产出需可控</td><td>【推导】</td></tr></tbody></table><h2 id="二、真实难点复盘" tabindex="-1">二、真实难点复盘 <a class="header-anchor" href="#二、真实难点复盘" aria-label="Permalink to &quot;二、真实难点复盘&quot;">​</a></h2><blockquote><p>下面这些是原设计记录里真实写出的坑，面试讲这些比讲&quot;我用了 XX 模式&quot;更有说服力。</p></blockquote><h3 id="难点-1-undo-恢复-dom-时污染历史-isrestoring" tabindex="-1">难点 1：Undo 恢复 DOM 时污染历史（<code>isRestoring</code>） <a class="header-anchor" href="#难点-1-undo-恢复-dom-时污染历史-isrestoring" aria-label="Permalink to &quot;难点 1：Undo 恢复 DOM 时污染历史（`isRestoring`）&quot;">​</a></h3><p><strong>现象</strong>：程序性恢复 DOM 会触发 contentEditable 的 <code>input</code>，被 <code>handleInput</code> 当成新编辑推入历史栈，连续 Ctrl+Z 出现&quot;撤销又被顶回去&quot;。</p><p><strong>本质</strong>：<strong>程序性 DOM 变更与用户输入走同一个事件通道</strong>，不区分来源就会互相污染。</p><p><strong>解</strong>：恢复期间上 <code>isRestoring</code> 锁，<code>handleInput</code> 检测到直接 return；所有恢复路径（undo / redo / <code>setTemplate</code>）共用同一把锁。详见 <a href="./07-history.html">07 · Undo/Redo</a>。</p><h3 id="难点-2-dom-重建后光标丢失" tabindex="-1">难点 2：DOM 重建后光标丢失 <a class="header-anchor" href="#难点-2-dom-重建后光标丢失" aria-label="Permalink to &quot;难点 2：DOM 重建后光标丢失&quot;">​</a></h3><p><strong>现象</strong>：模型更新会重建 / patch DOM，浏览器 Selection 随之失效。</p><p><strong>解</strong>：编辑器自己维护<strong>模型坐标</strong>选区（<code>nodeId + offset</code>），DOM 变更前保存、变更后 <code>positionToDOM</code> 翻译回浏览器 Range。前提是节点 ID 稳定。详见 <a href="./02-document-model.html">02 · 文档模型与选区</a>。</p><h3 id="难点-3-中文输入法-ime-与选区冲突" tabindex="-1">难点 3：中文输入法（IME）与选区冲突 <a class="header-anchor" href="#难点-3-中文输入法-ime-与选区冲突" aria-label="Permalink to &quot;难点 3：中文输入法（IME）与选区冲突&quot;">​</a></h3><p><strong>现象</strong>：拼音输入过程中会触发多次中间态，若每次都更新选区 / 模型，会打断输入。</p><p><strong>解</strong>：<code>compositionstart</code> 时冻结选区更新，<code>compositionend</code> 后一次性提交。详见 <a href="./02-document-model.html">02 · 文档模型与选区</a>。</p><h3 id="难点-4-首次加载和后续更新两套逻辑容易分叉" tabindex="-1">难点 4：首次加载和后续更新两套逻辑容易分叉 <a class="header-anchor" href="#难点-4-首次加载和后续更新两套逻辑容易分叉" aria-label="Permalink to &quot;难点 4：首次加载和后续更新两套逻辑容易分叉&quot;">​</a></h3><p><strong>解</strong>：统一 <code>reconcile</code> 接口，容器空不空都由它判断，首次加载只是&quot;oldChildren 为空&quot;的特例；首次挂载再用 DocumentFragment 离屏构建，减少 reflow。详见 <a href="./04-render-engine.html">04 · 渲染引擎</a>。</p><h3 id="难点-5-复杂容器重建会丢状态、子节点闪动" tabindex="-1">难点 5：复杂容器重建会丢状态、子节点闪动 <a class="header-anchor" href="#难点-5-复杂容器重建会丢状态、子节点闪动" aria-label="Permalink to &quot;难点 5：复杂容器重建会丢状态、子节点闪动&quot;">​</a></h3><p><strong>现象</strong>：condition / loop 内部有折叠状态和较深的子树，若属性一变就整块重建，会丢失折叠状态并造成子节点闪动。</p><p><strong>解</strong>：Handler 的 <code>update</code> 做成<strong>可选</strong>——复杂组件实现 <code>update</code> 原地 patch 自身属性（再递归 reconcile 子节点），简单组件不实现、直接重建。详见 <a href="./04-render-engine.html">04 · 渲染引擎</a>。</p><h3 id="难点-6-连续打字产生几十条历史" tabindex="-1">难点 6：连续打字产生几十条历史 <a class="header-anchor" href="#难点-6-连续打字产生几十条历史" aria-label="Permalink to &quot;难点 6：连续打字产生几十条历史&quot;">​</a></h3><p><strong>解</strong>：快照 <code>push</code> 做 500ms 节流，连续输入合并为一次快照，避免一次 undo 只退一个字符。详见 <a href="./07-history.html">07 · Undo/Redo</a>。</p><h3 id="补充-输入受控-vs-工具受控" tabindex="-1">补充：输入受控 vs 工具受控 <a class="header-anchor" href="#补充-输入受控-vs-工具受控" aria-label="Permalink to &quot;补充：输入受控 vs 工具受控&quot;">​</a></h3><p>这是原项目在面试复盘时明确过的设计选择：<strong>输入不受控（用户直接敲 contentEditable，DOM 先变、再同步回模型），工具操作受控（走 Command 改模型、再渲染 DOM）</strong>。前者保证打字手感，后者保证结构可控。</p><h2 id="三、与简历口径的技术对照" tabindex="-1">三、与简历口径的技术对照 <a class="header-anchor" href="#三、与简历口径的技术对照" aria-label="Permalink to &quot;三、与简历口径的技术对照&quot;">​</a></h2><p>简历上的成果，背后分别靠什么机制支撑（面试被追问时往下接）：</p><table tabindex="0"><thead><tr><th>简历表述</th><th>技术支撑</th></tr></thead><tbody><tr><td>单份模板维护成本从 2 小时降至分钟级</td><td>可视化编辑（工具 = Command + Handler）+ 在线填变量预览（<a href="./05-tools.html">05</a> / <a href="./06-serialization.html">06</a>）</td></tr><tr><td>模板生产能力下放给业务人员，自助化</td><td>变量显示友好 <code>label</code>、编辑区不见模板语法；Web Component 一键接入（<a href="./05-tools.html">05</a> / <a href="./08-embedding.html">08</a>）</td></tr><tr><td>内部用 Command 模式统一封装，可扩展 + 撤销/重做</td><td>Command + CommandContext（<a href="./03-command-engine.html">03</a>）、快照 Undo/Redo（<a href="./07-history.html">07</a>）</td></tr><tr><td>HTML 自适应布局、所见即所得</td><td>内容样式内联 + 单一数据源，预览与生产同源（<a href="./01-overview.html">01</a> / <a href="./06-serialization.html">06</a>）</td></tr></tbody></table><h2 id="四、高频追问-q-a" tabindex="-1">四、高频追问 Q&amp;A <a class="header-anchor" href="#四、高频追问-q-a" aria-label="Permalink to &quot;四、高频追问 Q&amp;A&quot;">​</a></h2><blockquote><p>按&quot;问题 / 答题要点&quot;给框架，具体数字和细节请按你的真实经历替换。</p></blockquote><p><strong>Q1：为什么自研，不直接用 Quill / Slate / CKEditor？</strong> 要点：通用富文本编辑器面向&quot;排版&quot;，而这个项目的核心是<strong>结构化语义节点</strong>（变量、条件、循环）→ 需要在编辑态就保留语义、并能精确序列化成 FreeMarker；接入任意富文本编辑器都要把它的模型映射成 DocNode，映射成本 + 失控风险高于自研内核。【推导】</p><p><strong>Q2：自研编辑器最大的风险是什么，怎么控制？</strong> 要点：编辑器难点集中在<strong>选区 / 光标、输入法、DOM 与模型同步</strong>。控制手段：模型坐标选区 + 稳定 ID（抗 DOM 重建）、<code>isRestoring</code> 锁隔离程序性变更、统一 reconcile 收敛渲染逻辑、Command + Handler 把&quot;改模型&quot;和&quot;改 DOM&quot;彻底分开。【文档 + 推导】</p><p><strong>Q3：编辑器整体架构画一下？</strong> 要点：四层（Web Component → React 外壳 → Core Engine → 样式策略），Core Engine 再分 model / engine / render / serialize 四包，依赖单向。见 <a href="./01-overview.html">01</a>。</p><p><strong>Q4：一次操作（比如插入变量）从点击到界面更新，经过哪些步骤？</strong> 要点：拖拽 drop → 计算模型 <code>Position</code> → <code>InsertVariableCommand</code> → Manager 存快照 + 建 Context → Command 改 DocNode → 靶向插入 / reconcile 更新 DOM → 派发 <code>template-change</code>。见 <a href="./03-command-engine.html">03</a> / <a href="./04-render-engine.html">04</a>。</p><p><strong>Q5：为什么撤销用快照不用逆操作？</strong> 要点：复合操作逆操作难写易错；快照天然覆盖任意复杂操作；DocNode JSON 体积可控 + 500ms 节流 + diff 靶向更新兜住性能。见 <a href="./07-history.html">07</a>。</p><p><strong>Q6：Undo 怎么做到不全量重渲染？</strong> 要点：diffDocNodes 找出 <code>dirtyIds</code> → 逐个 patch（删除 / 恢复 / 属性变更三类），复用未变的 DOM。见 <a href="./07-history.html">07</a>。</p><p><strong>Q7：模板保存和渲染的契约是什么？</strong> 要点：<strong>单一数据源</strong>——数据库只存 DocNode JSON，模板字符串是派生物；编辑、预览、生产渲染都从同一份 JSON 派生，因此&quot;预览 = 实际发出&quot;是机制保证而非人工对齐。见 <a href="./06-serialization.html">06</a>。</p><p><strong>Q8：新增一种工具（比如&quot;插入签名&quot;）要改哪些地方？</strong> 要点：<strong>三处，不动引擎</strong>——新增一个 Command（改模型）、一个 DOMHandler（渲染该节点类型）、一个触发入口（工具栏 / 拖拽）；只改 <code>handlerMap</code> 注册。见 <a href="./05-tools.html">05 · 工具设计</a> 开篇。</p><p><strong>Q9：邮件客户端兼容怎么处理？</strong> 要点：内容样式内联、Email 模式走表格布局 + 受限 CSS 子集、按 <code>compatibility</code> 设置区分兼容级别；本质上&quot;编辑即输出&quot;，所以兼容约束落在渲染 / 序列化环节而不是事后修。见 <a href="./01-overview.html">01</a>。</p><p><strong>Q10：为什么不用 diff 做日常编辑，却用它做 Undo？</strong> 要点：日常编辑的事件<strong>知道改了什么</strong>（操作类型 + 目标 + 内容），直接靶向更新；只有从快照恢复时&quot;不知道该改哪里&quot;，才需要 diff。见 <a href="./04-render-engine.html">04</a>。</p><p><strong>Q11：如果支持多人协作，架构要怎么改？</strong> 要点（扩展性追问，项目未实现，讲思路即可）：DocNode 是天然 CRDT / OT 的作用对象；模型坐标选区可映射成协同光标；Command 是操作单元，可作为协作操作的传输单元。分层已经把&quot;数据&quot;和&quot;视图&quot;分开，接入协同主要在 engine 层。【推导】</p><p><strong>Q12：如果重做一遍，会有什么不同？</strong> 要点：把 Handler 契约、<code>update</code> 的边界、<code>isRestoring</code> 这类&quot;程序性 vs 用户性变更&quot;的区分在架构层就固化；把内容样式的内联生成做成独立可测的子层。<strong>按你的真实反思替换</strong>。【推导】</p><h2 id="五、一句话总结" tabindex="-1">五、一句话总结 <a class="header-anchor" href="#五、一句话总结" aria-label="Permalink to &quot;五、一句话总结&quot;">​</a></h2><p>这个项目的架构主线可以概括为：<strong>用一棵文档树（DocNode）当唯一事实来源，用 Command 收口所有操作，用可选的 Handler 契约 + 统一 reconcile 同步视图，用快照兜住撤销</strong>——每一层都在为&quot;编辑器产出必须可控、可序列化、所见即所得&quot;服务。</p><hr><p><strong>上一篇</strong>：<a href="./08-embedding.html">08 · Web Component 接入</a> ｜ <strong>回到</strong>：<a href="./">总览</a></p>',46)])])}const g=o(a,[["render",n]]);export{p as __pageData,g as default};
